:root {
  --bg: oklch(0.985 0.004 165);
  --surface: oklch(1 0 0);
  --head: oklch(0.955 0.006 165);
  --hover: oklch(0.965 0.012 165);
  --line: oklch(0.92 0.006 165);
  --border: oklch(0.62 0.01 165);
  --ink: oklch(0.22 0.012 165);
  --muted: oklch(0.47 0.012 165);
  --accent: oklch(0.45 0.09 165);
  --paid: oklch(0.48 0.11 155);
  --overdue: oklch(0.5 0.17 27);
  --ring: 2px solid var(--accent);
  --ease: cubic-bezier(0.22, 1, 0.36, 1);
  color-scheme: light;
}

* { box-sizing: border-box; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font: 0.875rem/1.5 system-ui, -apple-system, "Segoe UI", sans-serif;
}
h1, h2 { margin: 0; text-wrap: balance; }
:focus-visible { outline: var(--ring); outline-offset: 2px; }
.sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

/* Header + What's new */
.bar {
  display: flex; align-items: center; justify-content: space-between;
  padding-block: 0.5rem; padding-inline: max(1.25rem, calc((100% - 72rem) / 2));
  border-block-end: 1px solid var(--line);
  background: var(--surface);
}
.wordmark { font-weight: 700; font-size: 1rem; letter-spacing: -0.01em; }
.news-toggle {
  min-height: 44px; padding-inline: 0.75rem;
  font: inherit; font-weight: 600; color: var(--accent);
  background: none; border: 1px solid transparent; border-radius: 6px; cursor: pointer;
}
.news-toggle:hover { background: var(--hover); }
.news-toggle::after { content: " ▾"; display: inline-block; transition: rotate 200ms var(--ease); }
.news-toggle[aria-expanded="true"]::after { rotate: 180deg; }

.news {
  display: grid; grid-template-rows: 0fr;
  background: var(--surface); border-block-end: 1px solid transparent;
  transition: grid-template-rows 220ms var(--ease), border-color 220ms;
}
.news.open { grid-template-rows: 1fr; border-color: var(--line); }
.news-inner { overflow: hidden; }
.news-list {
  list-style: none; margin: 0;
  padding-block: 0.75rem; padding-inline: max(1.25rem, calc((100% - 72rem) / 2));
  display: grid; gap: 0.375rem;
  opacity: 0; translate: 0 -4px; transition: opacity 220ms var(--ease), translate 220ms var(--ease);
}
.news.open .news-list { opacity: 1; translate: 0; }
.news-list time { color: var(--muted); font-variant-numeric: tabular-nums; display: inline-block; min-width: 3.5rem; }

/* Signature: status glyphs. Shape carries the state, colour only reinforces it. */
.glyph { display: inline-block; flex: none; width: 8px; height: 8px; margin-inline-end: 0.5rem; vertical-align: 0.05em; border-radius: 50%; }
.glyph-draft { border: 1.5px dashed var(--muted); }
.glyph-sent { border: 1.5px solid var(--ink); }
.glyph-paid { background: var(--paid); }
.glyph-overdue { background: var(--overdue); border-radius: 1px; rotate: 45deg; width: 7px; height: 7px; }

/* Hero + form */
main { max-width: 72rem; margin-inline: auto; padding: 3rem 1.25rem 4rem; }
.top { display: grid; gap: 2.5rem; align-items: start; margin-block-end: 3.5rem; }
@media (min-width: 52rem) {
  .top { grid-template-columns: 1fr minmax(20rem, 24rem); gap: 4rem; padding-block-start: 2rem; }
}
h1 { font-size: 2.25rem; line-height: 1.15; letter-spacing: -0.02em; max-width: 18ch; }
.lede { margin: 0.75rem 0 0; font-size: 20px; line-height: 1.45; color: var(--muted); max-width: 38ch; }

