input:hover { border-color: var(--ink); }
input[aria-invalid="true"] { border-color: var(--overdue); border-width: 2px; }
.err { margin: 0; color: var(--overdue); font-weight: 500; }
.err:empty { display: none; }
.err::before { content: ""; display: inline-block; width: 7px; height: 7px; margin-inline-end: 0.5rem; background: var(--overdue); rotate: 45deg; border-radius: 1px; vertical-align: 0.05em; }
.check { display: flex; align-items: center; gap: 0.5rem; min-height: 44px; cursor: pointer; }
.check input { width: 1.125rem; height: 1.125rem; accent-color: var(--accent); margin: 0; }
.primary {
  min-height: 44px; font: inherit; font-weight: 600; color: var(--surface);
  background: var(--accent); border: 0; border-radius: 6px; cursor: pointer;
}
.primary:hover { background: oklch(0.39 0.09 165); }
.primary:active { translate: 0 1px; }
.primary[aria-disabled="true"] { cursor: progress; opacity: 0.8; }
.status { margin: 0; color: var(--muted); }
.status:empty { display: none; }

