.preview-head { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 0.25rem 1rem; margin-block-end: 0.5rem; }
.preview-head h2 { font-size: 1rem; }
.meta { margin: 0; color: var(--muted); }

