td.mono { font-family: ui-monospace, "Cascadia Mono", Consolas, monospace; font-size: 0.75rem; }

thead th {
  position: sticky; top: 0; z-index: 2; padding: 0;
  background: var(--head); border-block-end-color: var(--border);
}
th button {
  display: flex; align-items: center; gap: 0.25rem; width: 100%; min-height: 2rem; padding: 0 0.75rem;
  font: inherit; font-weight: 600; color: var(--ink); background: none; border: 0; cursor: pointer;
}
th.num button { justify-content: flex-end; }
th button:hover { background: var(--hover); }
th button span { color: var(--muted); font-weight: 400; min-width: 0.75em; }
th button span::before { content: "↕"; opacity: 0.6; }
th[aria-sort="ascending"] button span::before { content: "↑"; opacity: 1; color: var(--ink); }
th[aria-sort="descending"] button span::before { content: "↓"; opacity: 1; color: var(--ink); }
@media (pointer: coarse) { th button { min-height: 44px; } }

