thead th:first-child { z-index: 3; background: var(--head); }
tbody tr:hover td { background: var(--hover); }

.st { display: inline-flex; align-items: center; }
.st-paid { color: var(--paid); }
.st-overdue { color: var(--overdue); font-weight: 600; }
