// What's new
const newsToggle = document.querySelector('.news-toggle');
const news = document.getElementById('news');
newsToggle.addEventListener('click', () => {
  const open = newsToggle.getAttribute('aria-expanded') !== 'true';
  newsToggle.setAttribute('aria-expanded', open);
  news.classList.toggle('open', open);
  news.inert = !open;
});

// Sign-in form: check a field on blur only once it's been typed in, re-check live once it's flagged.
const form = document.getElementById('signin');
const button = form.querySelector('.primary');
const formStatus = document.getElementById('form-status');
const fields = [...form.querySelectorAll('input[required]')];
const messages = {
  email: v => v.valueMissing ? 'Enter your email address.' : v.typeMismatch ? 'Enter a full email address, like name@yourfirm.com.' : '',
  password: v => v.valueMissing ? 'Enter your password.' : '',
};

function check(input) {
  const msg = messages[input.name](input.validity);
  document.getElementById(input.id + '-err').textContent = msg;
  if (msg) input.setAttribute('aria-invalid', 'true');
  else input.removeAttribute('aria-invalid');
  return !msg;
}

for (const input of fields) {
  input.addEventListener('input', () => {
    input.dataset.dirty = '1';
    if (input.hasAttribute('aria-invalid')) check(input);
  });
  input.addEventListener('blur', () => { if (input.dataset.dirty) check(input); });
}

form.addEventListener('submit', e => {
  e.preventDefault();
  if (button.getAttribute('aria-disabled') === 'true') return;
  formStatus.textContent = '';
  const invalid = fields.filter(i => !check(i));
  if (invalid.length) return invalid[0].focus();

  button.setAttribute('aria-disabled', 'true');
  button.textContent = 'Signing in…';
  // ponytail: no account server exists yet. Replace this timeout with the real session request.
  setTimeout(() => {
    button.removeAttribute('aria-disabled');
    button.textContent = 'Sign in';
    formStatus.textContent = "Sign-in isn't connected yet. This page is a preview without an account server.";
  }, 600);
});

// Invoice preview (sample data, generated relative to today so statuses stay believable)
const clients = ['Harbor Street Dental', 'Mill Lane Bakery', 'Okafor and Reyes Architects', 'Northgate Plumbing',
  'Pinecrest Veterinary', 'Linden Yoga Studio', 'Castillo Landscaping', 'Brightwater Cafe', 'Hale Joinery',
  'Summit Physio', 'Redfern Print Shop', 'Quayside Florist', 'Marlow Electrical', 'Ashby Family Law'];
const today = new Date();
today.setHours(0, 0, 0, 0);
const addDays = (d, n) => { const x = new Date(d); x.setDate(x.getDate() + n); return x; };

const invoices = Array.from({ length: 40 }, (_, i) => {
  const issued = addDays(today, -(i * 2 + (i % 3)));
  const due = addDays(issued, i % 4 === 0 ? 14 : 30);
  const late = Math.round((today - due) / 864e5);
  const status = i < 2 ? 'draft' : i % 3 === 1 || (i > 30 && i % 5) ? 'paid' : late > 0 ? 'overdue' : 'sent';
  return { client: clients[(i * 5) % clients.length], number: `TH-${2461 - i}`, issued, due,
    amount: 180 + ((i * 7919) % 4700) + ((i * 37) % 100) / 100, status, late };
});

const severity = { overdue: 0, sent: 1, draft: 2, paid: 3 };
const sortValue = {
  client: r => r.client,
  number: r => r.number,
  issued: r => +r.issued,
  due: r => +r.due,
  amount: r => r.amount,
  status: r => severity[r.status] * 1e4 - r.late, // most-late overdue first
};
const statusLabel = { draft: 'Draft', sent: 'Sent', paid: 'Paid', overdue: 'Overdue' };
const fmtDate = new Intl.DateTimeFormat(undefined, { month: 'short', day: 'numeric' });
const fmtMoney = new Intl.NumberFormat(undefined, { style: 'currency', currency: 'USD' });

const tbody = document.getElementById('rows');
const headers = [...document.querySelectorAll('thead th')];
const params = new URLSearchParams(location.search);
let key = sortValue[params.get('sort')] ? params.get('sort') : 'issued';
let dir = params.get('dir') === 'asc' ? 1 : -1;

function render() {
  const rows = invoices.slice().sort((a, b) => {
    const x = sortValue[key](a), y = sortValue[key](b);
    return (typeof x === 'string' ? x.localeCompare(y) : x - y) * dir;
  });
  tbody.innerHTML = rows.map(r => `<tr>
    <td title="${r.client}">${r.client}</td>
    <td class="mono">${r.number}</td>
    <td>${fmtDate.format(r.issued)}</td>
    <td>${fmtDate.format(r.due)}</td>
    <td class="num">${fmtMoney.format(r.amount)}</td>
    <td><span class="st st-${r.status}"><i class="glyph glyph-${r.status}" aria-hidden="true"></i>${statusLabel[r.status]}${
      r.status === 'overdue' ? `<span class="late"><span aria-hidden="true">${r.late}d</span><span class="sr">, ${r.late} days late</span></span>` : ''}</span></td>
  </tr>`).join('');
  for (const th of headers) {
    if (th.dataset.key === key) th.setAttribute('aria-sort', dir > 0 ? 'ascending' : 'descending');
    else th.removeAttribute('aria-sort');
  }
}

for (const th of headers) {
  th.querySelector('button').addEventListener('click', () => {
    dir = th.dataset.key === key ? -dir : 1;
    key = th.dataset.key;
    render();
    params.set('sort', key);
    params.set('dir', dir > 0 ? 'asc' : 'desc');
    history.replaceState(null, '', '?' + params);
    document.getElementById('sort-status').textContent =
      `Sorted by ${th.textContent.trim()}, ${dir > 0 ? 'ascending' : 'descending'}`;
  });
}

document.getElementById('count').textContent = `${invoices.length} invoices`;
render();

